// Race condition: two async operations on shared state
let balance = 1000;

async function withdraw(amount, label) {
  // Simulate a read-then-write that crosses an async boundary (like a DB round-trip)
  const current = balance;                     // READ
  await new Promise(r => setTimeout(r, 10));   // simulated latency — scheduler can switch here
  balance = current - amount;                  // WRITE (with stale 'current'!)
  console.log(`${label}: withdrew ${amount}, new balance: ${balance}`);
}

// UNSAFE: both reads happen before either write
await Promise.all([
  withdraw(200, 'Alice'),
  withdraw(300, 'Bob')
]);
console.log('Final balance (wrong):', balance);
// Expected: 1000 - 200 - 300 = 500
// Actual:   1000 - 200 = 800  OR  1000 - 300 = 700  — one withdrawal is lost!

// ── FIX: serialize with an async mutex ────────────────────────────────────────
function createMutex() {
  let queue = Promise.resolve();  // the current tail of the promise chain
  return function withLock(fn) {
    // Each new task is chained AFTER the previous one completes
    // This is the key insight: promise chaining IS mutual exclusion for async code
    queue = queue.then(fn);
    return queue;
  };
}

const lock = createMutex();
balance = 1000;

// Now each withdrawal waits for the previous one to fully finish before reading balance
lock(() => withdraw(200, 'Alice (safe)'));
lock(() => withdraw(300, 'Bob   (safe)'));
// Guaranteed order: Alice reads 1000, writes 800; then Bob reads 800, writes 500
// Final balance: 500 ✓

// ── Counting semaphore: limit concurrency to N ────────────────────────────────
function createSemaphore(n) {
  let count = n;
  const queue = [];
  return {
    wait() {
      if (count > 0) { count--; return Promise.resolve(); }
      // No capacity — return a promise that resolves when signal() is called
      return new Promise(resolve => queue.push(resolve));
    },
    signal() {
      if (queue.length > 0) {
        queue.shift()();  // wake the next waiting thread
      } else {
        count++;
      }
    }
  };
}

const dbPool = createSemaphore(3);  // at most 3 concurrent DB operations

async function queryDatabase(id) {
  await dbPool.wait();         // block if 3 others are already in progress
  try {
    console.log(`DB query ${id} started`);
    await new Promise(r => setTimeout(r, 50));  // simulate DB latency
    console.log(`DB query ${id} done`);
  } finally {
    dbPool.signal();           // always release, even on error
  }
}

// ── Strategy 1: Lock Ordering (breaks Circular Wait) ──────────────────────────
// WRONG: acquiring locks in arbitrary order can deadlock
function transferWrong(fromAccount, toAccount, amount) {
  fromAccount.lock();   // Thread A acquires account 42's lock
  // scheduler switch → Thread B acquires account 99's lock
  toAccount.lock();     // Thread A now waits for account 99 — DEADLOCK POSSIBLE
  fromAccount.balance -= amount;
  toAccount.balance   += amount;
  toAccount.unlock();
  fromAccount.unlock();
}

// CORRECT: always acquire in ascending ID order — circular wait cannot form
function transferSafe(accountA, accountB, amount) {
  const [first, second] = accountA.id < accountB.id
    ? [accountA, accountB]
    : [accountB, accountA];

  first.lock();
  second.lock();
  // No matter how many threads call transferSafe concurrently,
  // they all agree on the same lock order → no cycle in the wait-for graph
  if (first === accountA) {
    accountA.balance -= amount;
    accountB.balance += amount;
  } else {
    accountA.balance -= amount;
    accountB.balance += amount;
  }
  second.unlock();
  first.unlock();
}

// ── Strategy 2: Timeout and Retry (breaks No Preemption) ─────────────────────
async function transferWithTimeout(fromAccount, toAccount, amount, maxRetries = 3) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const acquiredFrom = await fromAccount.tryLock(200);  // 200ms timeout
    if (!acquiredFrom) {
      // Could not acquire first lock — no point trying second; retry after backoff
      const jitter = Math.random() * 50;
      await sleep(100 * attempt + jitter);  // exponential backoff with jitter
      continue;
    }
    try {
      const acquiredTo = await toAccount.tryLock(200);
      if (!acquiredTo) {
        fromAccount.unlock();  // release what we hold — break Hold-and-Wait
        const jitter = Math.random() * 50;
        await sleep(100 * attempt + jitter);
        continue;
      }
      try {
        fromAccount.balance -= amount;
        toAccount.balance   += amount;
        return { success: true, attempt };
      } finally {
        toAccount.unlock();
      }
    } finally {
      fromAccount.unlock();
    }
  }
  throw new Error(`Transfer failed after ${maxRetries} attempts — possible deadlock`);
}

const sleep = ms => new Promise(r => setTimeout(r, ms));
